use std::thread;

struct Shared {
    m: Mutex<bool>,
    cv: Condvar,
}

fn main() {
    let shared = Arc::new(Shared {
        m: Mutex::new(false),
        cv: Condvar::new(),
    });

    let waiter_shared = Arc::clone(&shared);
    let waiter = thread::spawn(move || {
        let mut ready = waiter_shared.m.lock().unwrap();
        while !*ready {
            ready = waiter_shared.cv.wait(ready).unwrap();
        }
        *ready
    });

