```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct WaiterState {
    announced: bool,
    notified: bool,
}

struct Shared {
    m1: Mutex<WaiterState>,
    m2: Mutex<WaiterState>,
    cv: Condvar,
    ready: Mutex<usize>,
    ready_cv: Condvar,
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(WaiterState {
            announced: false,
            notified: false,
        }),
        m2: Mutex::new(WaiterState {
            announced: false,
            notified: false,
        }),
        cv: Condvar::new(),
        ready: Mutex::new(0),
        ready_cv: Condvar::new(),
    });

    let s1 = Arc::clone(&shared);
    let w1 = thread::spawn(move || {
        let mut guard = s1.m1.lock().unwrap();
        guard.announced = true;
        {
            let mut r = s1.ready.lock().unwrap();
            *r += 1;
            s1.ready_cv.notify_all();
        }
        while !guard.notified {
            guard = s1.cv.wait(guard).unwrap();
        }
    });

    let s2 = Arc::clone(&shared);
    let w2 = thread::spawn(move || {
        let mut guard = s2.m2.lock().unwrap();
        guard.announced = true;
        {
            let mut r = s2.ready.lock().unwrap();
            *r += 1;
            s2.ready_cv.notify_all();
        }
        while !guard.notified {
            guard = s2.cv.wait(guard).unwrap();
        }
    });

    let s3 = Arc::clone(&shared);
    let notifier = thread::spawn(move || {
        {
            let mut r = s3.ready.lock().unwrap();
            while *r < 2 {
                r = s3.ready_cv.wait(r).unwrap();
            }
        }
        {
            let mut g1 = s3.m1.lock().unwrap();
            g1.notified = true;
            s3.cv.notify_all();
        }
        {
            let mut g2 = s3.m2.lock().unwrap();
            g2.notified = true;
            s3.cv.notify_all();
        }
    });

    w1.join().unwrap();
    w2.join().unwrap();
    notifier.join().unwrap();

    println!("DONE done=1");
}
```

```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Semaphore {
    mutex: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(count: usize) -> Self {
        Semaphore {
            mutex: Mutex::new(count),
            cv: Condvar::new(),
        }
    }

    fn wait(&self) {
        let mut count = self.mutex.lock().unwrap();
        while *count == 0 {
            count = self.cv.wait(count).unwrap();
        }
        *count -= 1;
    }

    fn signal(&self) {
        let mut count = self.mutex.lock().unwrap();
        *count += 1;
        self.cv.notify_one();
    }
}

fn main() {
    let m1 = Arc::new(Mutex::new(false));
    let m2 = Arc::new(Mutex::new(false));
    let cv = Arc::new(Condvar::new());
    let ready = Arc::new(Semaphore::new(0));

    let m1_w1 = Arc::clone(&m1);
    let cv_w1 = Arc::clone(&cv);
    let ready_w1 = Arc::clone(&ready);

    let w1 = thread::spawn(move || {
        let mut guard = m1_w1.lock().unwrap();
        ready_w1.signal();
        while !*guard {
            guard = cv_w1.wait(guard).unwrap();
        }
        *guard = true;
    });

    let m2_w2 = Arc::clone(&m2);
    let cv_w2 = Arc::clone(&cv);
    let ready_w2 = Arc::clone(&ready);

    let w2 = thread::spawn(move || {
        let mut guard = m2_w2.lock().unwrap();
        ready_w2.signal();
        while !*guard {
            guard = cv_w2.wait(guard).unwrap();
        }
        *guard = true;
    });

    let m1_n = Arc::clone(&m1);
    let m2_n = Arc::clone(&m2);
    let cv_n = Arc::clone(&cv);
    let ready_n = Arc::clone(&ready);

    let notifier = thread::spawn(move || {
        ready_n.wait();
        ready_n.wait();

        let mut g1 = m1_n.lock().unwrap();
        let mut g2 = m2_n.lock().unwrap();

        *g1 = true;
        *g2 = true;

        cv_n.notify_all();
    });

    w1.join().unwrap();
    w2.join().unwrap();
    notifier.join().unwrap();

    println!("DONE done=1");
}
```

