    }
    std::hint::black_box(x);
}

fn main() {
    let m = Arc::new(Mutex::new(0u64));
    let acc = Arc::new(Mutex::new(0u64));

    let m1 = Arc::clone(&m);
    let acc1 = Arc::clone(&acc);
    let w1 = thread::spawn(move || {
        let mut guard = m1.lock().unwrap();
        compute();
        *guard += 1;
        let mut a = acc1.lock().unwrap();
