        ready_w1.signal();
        while !*guard {
            guard = cv1_w1.wait(guard).unwrap();
        }
        *guard = true;
    });

    let m2_w2 = Arc::clone(&m2);
    let cv2_w2 = Arc::clone(&cv2);
    let ready_w2 = Arc::clone(&ready);

    let w2 = thread::spawn(move || {
        let mut guard = m2_w2.lock().unwrap();
        ready_w2.signal();
        while !*guard {
