        }
        *guard = true;
    });

    let m1_notifier = Arc::clone(&m1);
    let m2_notifier = Arc::clone(&m2);
    let cv1_notifier = Arc::clone(&cv1);
    let cv2_notifier = Arc::clone(&cv2);
    let ready_notifier = Arc::clone(&ready);

    let notifier = thread::spawn(move || {
