        // Take first lock b
        let _gb = b2.lock().unwrap();
        // Signal that b has taken its first lock
        sb2.release();
        // Wait for a to take its first lock
        sa2.acquire();
        // Take second lock a
        let _ga = a2.lock().unwrap();
        // Critical section
        {
            let mut f = flag2.lock().unwrap();
            *f += 1;
        }
        // Locks released on drop
    });

